// File: src/test/java/com/bank/java8/BreakingChangesTest.java
package com.bank.java8;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

class BreakingChangesTest {

    boolean breaksOnJava17(String concern) {
        return switch (concern) {
            case "reflect-jdk-internal", "nashorn", "java-ee-module" -> true;
            case "stream-api", "records" -> false;
            default -> false;
        };
    }

    @Test
    void classifiesBreakingChanges() {
        assertThat(breaksOnJava17("reflect-jdk-internal")).isTrue();
        assertThat(breaksOnJava17("nashorn")).isTrue();
        assertThat(breaksOnJava17("stream-api")).isFalse();
    }
}
